            DatabaseNode databaseNode = nodeMap.get(connection);
            if (databaseNode != null) {
                removeNode(databaseNode, PROGRESS_NODE_TITLE);
                populateFeatureClasses(connection, databaseNode);
                if (treeModel != null) {
